using System.Security.Claims;using LocalPro.Web.Data;using LocalPro.Web.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace LocalPro.Web.Pages;[Authorize]public class FavoritesModel(AppDbContext db,Marketplace m):PageModel{public List<Domain.Professional> Items{get;set;}=[];public async Task OnGetAsync(){var id=User.FindFirstValue(ClaimTypes.NameIdentifier)!;var ids=await db.Favorites.Where(f=>f.UserId==id).Select(f=>f.ProfessionalId).ToListAsync();Items=(await m.Search()).Where(p=>ids.Contains(p.Id)).ToList();}public async Task<IActionResult> OnPostAsync(int pro){var id=User.FindFirstValue(ClaimTypes.NameIdentifier)!;var f=await db.Favorites.SingleOrDefaultAsync(f=>f.UserId==id&&f.ProfessionalId==pro);if(f!=null){db.Remove(f);await db.SaveChangesAsync();}return RedirectToPage();}}
